// analyzer/enums.ts:40
#[derive(Clone)]
#[derive(jsrt::Trace)]
pub struct EnumEvalStackEntry {
    pub class_type: ClassType,
    pub member_name: String,
}

thread_local! {
    // analyzer/enums.ts:47
    // This stack is used to prevent infinite recursion when evaluating
    // enum members that refer to other enum members.
    pub(crate) static ENUM_EVAL_STACK: RefCell<Vec<EnumEvalStackEntry>> = {
        // Holds evaluator handles while a file is checked: a collector root.
        jsrt::heap::add_root(|t| ENUM_EVAL_STACK.with(|s| jsrt::Trace::trace(s, t)));
        RefCell::new(Vec::new())
    };
}

// analyzer/enums.ts:50
// Determines whether the class is an Enum metaclass or a subclass thereof.
pub fn is_enum_metaclass(class_type: ClassType) -> bool {
    let mro = class_type.d().shared.get().mro.borrow().clone();
    mro.iter().any(|&mro_class| {
        is_class(mro_class)
            && ClassType::is_built_in(
                ClassType(mro_class),
                Some(&[jsrt::atom!("EnumMeta"), jsrt::atom!("EnumType")]),
            )
    })
}

// analyzer/enums.ts:58
// Determines whether this is an enum class that has at least one enum
// member defined.
pub fn is_enum_class_with_members(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    node_info: &AnalyzerNodeInfoAccessor,
) -> bool {
    if !is_class(class_type.0) || !ClassType::is_enum_class(class_type) {
        return false;
    }

    // Determine whether the enum class defines a member.
    let symbol_table = ClassType::get_symbol_table(class_type);
    // `symbolTable.keys()` is a live iterator: it also visits names added
    // during the walk.
    let mut index = 0;
    loop {
        let name = symbol_table
            .borrow()
            .get_index(index)
            .map(|(name, _)| name.clone());
        let Some(name) = name else {
            break;
        };
        let symbol_type = transform_type_for_enum_member(
            evaluator,
            class_type,
            &name,
            node_info.reader(),
            false,
            0,
        );
        if let Some(symbol_type) = symbol_type
            && is_class_instance(symbol_type)
            && ClassType::is_same_generic_class(
                ClassType(symbol_type),
                ClassType::clone_as_instance(class_type, true),
                0,
            )
        {
            return true;
        }
        index += 1;
    }

    false
}

// analyzer/enums.ts:84
// Creates a new custom enum class with named values.
pub fn create_enum_type(
    evaluator: &TypeEvaluator,
    error_node: ExpressionNode,
    enum_class: ClassType,
    arg_list: &[Arg],
    node_info: &AnalyzerNodeInfoAccessor,
) -> Option<ClassType> {
    // `strings.map((s) => s.d.value).join('')`.
    let join_string_values = |strings: &[P<ParseNode>]| {
        let mut joined = JsString::from("");
        for s in strings {
            let value = match s.d() {
                ParseNodeDetails::String(d) => &d.value,
                ParseNodeDetails::FormatString(d) => &d.value,
                _ => unreachable!("a string list holds string nodes"),
            };
            joined = joined.concat(value);
        }
        joined
    };

    let file_info = node_info.get_file_info(error_node);
    let is_repr_enum = is_repr_enum_class(enum_class);

    if arg_list.is_empty() {
        return None;
    }

    let name_arg = &arg_list[0];
    let name_value_expression = match name_arg.value_expression() {
        Some(value_expression) if name_arg.arg_category() == ArgCategory::Simple => {
            value_expression
        }
        _ => return None,
    };
    let name_string_list = StringListNode::cast(name_value_expression)?;
    let name_strings = name_string_list.d().strings.borrow().clone();
    if name_strings.len() != 1 || name_strings[0].node_type != ParseNodeType::String {
        return None;
    }

    let class_name = join_string_values(&name_strings).to_string_lossy();
    let class_type = ClassType::create_instantiable(
        &class_name,
        &get_class_full_name(error_node, &file_info.module_name, &class_name),
        &file_info.module_name,
        &file_info.file_uri,
        ClassTypeFlags::EnumClass | ClassTypeFlags::ValidTypeAliasClass,
        get_type_source_id(error_node),
        /* declaredMetaclass */ None,
        enum_class.d().shared.get().effective_metaclass.get(),
        None,
    );
    Rc::make_mut(&mut *class_type
        .d()
        .shared
        .get()
        .base_classes
        .borrow_mut())
        .push(enum_class.0);
    compute_mro_linearization(class_type);

    let class_fields = ClassType::get_symbol_table(class_type);
    class_fields.set(
        "__class__",
        Symbol::create_with_type(
            SymbolFlags::ClassMember | SymbolFlags::IgnoredForProtocolMatch,
            class_type.0,
            None,
        ),
    );

    if arg_list.len() < 2 {
        return None;
    }

    let init_arg = &arg_list[1];
    let init_value_expression = match init_arg.value_expression() {
        Some(value_expression) if init_arg.arg_category() == ArgCategory::Simple => {
            value_expression
        }
        _ => return None,
    };

    let int_class_type = evaluator.get_built_in_type(error_node, "int");
    if !is_instantiable_class(int_class_type) {
        return None;
    }
    let int_class_type = ClassType(int_class_type);
    let class_instance_type = ClassType::clone_as_instance(class_type, true);

    // The Enum functional form supports various forms of arguments:
    //   Enum('name', 'a b c')
    //   Enum('name', 'a,b,c')
    //   Enum('name', ['a', 'b', 'c'])
    //   Enum('name', ('a', 'b', 'c'))
    //   Enum('name', (('a', 1), ('b', 2), ('c', 3)))
    //   Enum('name', [('a', 1), ('b', 2), ('c', 3))]
    //   Enum('name', {'a': 1, 'b': 2, 'c': 3})
    if let Some(init_string_list) = StringListNode::cast(init_value_expression) {
        let init_strings = init_string_list.d().strings.borrow().clone();
        // Don't allow format strings in the init arg.
        if !init_strings
            .iter()
            .all(|str| str.node_type == ParseNodeType::String)
        {
            return None;
        }

        let init_str = join_string_values(&init_strings);
        let init_str = init_str.js_trim();

        // Split by comma or whitespace.
        // JS `/[\s,]+/`. Splitting the decoded text splits at the same places:
        // a lone surrogate decodes to U+FFFD, which is not a separator.
        static ENTRY_SEPARATOR_REG_EX: LazyLock<Regex> =
            LazyLock::new(|| Regex::new(&format!("[{WHITESPACE_IN_CLASS},]+")).unwrap());
        let init_str = String::from_utf16_lossy(init_str);
        let entry_names: Vec<&str> = ENTRY_SEPARATOR_REG_EX.split(&init_str).collect();

        for (index, &entry_name) in entry_names.iter().enumerate() {
            if entry_name.is_empty() {
                return None;
            }

            let value_type = ClassType::clone_with_literal(
                ClassType::clone_as_instance(int_class_type, true),
                Some(LiteralValue::Number((index + 1) as f64)),
            );

            let class_shared = class_type.d().shared.get();
            let enum_literal = EnumLiteral::new(
                class_shared.full_name.to_string(),
                class_shared.name.to_string(),
                entry_name.to_string(),
                value_type.0,
                is_repr_enum,
            );

            let new_symbol = Symbol::create_with_type(
                SymbolFlags::ClassMember,
                ClassType::clone_with_literal(
                    class_instance_type,
                    Some(LiteralValue::EnumLiteral(enum_literal)),
                )
                .0,
                None,
            );

            class_fields.set(entry_name, new_symbol);
        }

        return Some(class_type);
    }

    if init_value_expression.node_type == ParseNodeType::List
        || init_value_expression.node_type == ParseNodeType::Tuple
    {
        let entries = match ListNode::cast(init_value_expression) {
            Some(list_node) => list_node.d().items.borrow().clone(),
            None => TupleNode(init_value_expression).d().items.borrow().clone(),
        };

        if entries.is_empty() {
            return None;
        }

        // Entries can be either string literals or tuples of a string
        // literal and a value. All entries must follow the same pattern.
        let mut is_simple_string = false;
        for (index, &entry) in entries.iter().enumerate() {
            if index == 0 {
                is_simple_string = entry.node_type == ParseNodeType::StringList;
            }

            let name_node: P<ParseNode>;
            let value_type: P<Type>;

            if entry.node_type == ParseNodeType::StringList {
                if !is_simple_string {
                    return None;
                }

                name_node = entry;
                value_type = ClassType::clone_with_literal(
                    ClassType::clone_as_instance(int_class_type, true),
                    Some(LiteralValue::Number((index + 1) as f64)),
                )
                .0;
            } else {
                // Not a tuple: `return undefined`.
                let entry_tuple = TupleNode::cast(entry)?;
                if is_simple_string {
                    return None;
                }

                let entry_items = entry_tuple.d().items.borrow().clone();
                if entry_items.len() != 2 {
                    return None;
                }
                name_node = entry_items[0];
                value_type = evaluator
                    .get_type_of_expression(entry_items[1], EvalFlags::None, None)
                    .type_
                    .get();
            }

            let name_string_list = StringListNode::cast(name_node)?;
            let name_strings = name_string_list.d().strings.borrow().clone();
            if name_strings.len() != 1 || name_strings[0].node_type != ParseNodeType::String {
                return None;
            }

            let entry_name = match name_strings[0].d() {
                ParseNodeDetails::String(d) => d.value.to_string_lossy(),
                _ => unreachable!("checked to be a string node"),
            };

            let class_shared = class_type.d().shared.get();
            let enum_literal = EnumLiteral::new(
                class_shared.full_name.to_string(),
                class_shared.name.to_string(),
                entry_name.clone(),
                value_type,
                is_repr_enum,
            );

            let new_symbol = Symbol::create_with_type(
                SymbolFlags::ClassMember,
                ClassType::clone_with_literal(
                    class_instance_type,
                    Some(LiteralValue::EnumLiteral(enum_literal)),
                )
                .0,
                None,
            );

            class_fields.set(&entry_name, new_symbol);
        }
    }

    if let Some(dictionary) = DictionaryNode::cast(init_value_expression) {
        let entries = dictionary.d().items.borrow().clone();
        if entries.is_empty() {
            return None;
        }

        for &entry in &entries {
            // Don't support dictionary expansion expressions.
            let key_entry = DictionaryKeyEntryNode::cast(entry)?;

            let name_node = key_entry.d().key_expr.get();
            let value_type = evaluator
                .get_type_of_expression(key_entry.d().value_expr.get(), EvalFlags::None, None)
                .type_
                .get();

            let name_string_list = StringListNode::cast(name_node)?;
            let name_strings = name_string_list.d().strings.borrow().clone();
            if name_strings.len() != 1 || name_strings[0].node_type != ParseNodeType::String {
                return None;
            }

            let entry_name = match name_strings[0].d() {
                ParseNodeDetails::String(d) => d.value.to_string_lossy(),
                _ => unreachable!("checked to be a string node"),
            };
            let class_shared = class_type.d().shared.get();
            let enum_literal = EnumLiteral::new(
                class_shared.full_name.to_string(),
                class_shared.name.to_string(),
                entry_name.clone(),
                value_type,
                is_repr_enum,
            );

            let new_symbol = Symbol::create_with_type(
                SymbolFlags::ClassMember,
                ClassType::clone_with_literal(
                    class_instance_type,
                    Some(LiteralValue::EnumLiteral(enum_literal)),
                )
                .0,
                None,
            );

            class_fields.set(&entry_name, new_symbol);
        }
    }

    Some(class_type)
}

// analyzer/enums.ts:316
// Performs the "magic" that the Enum metaclass does at runtime when it
// transforms a value into an enum instance. If the specified name isn't
// an enum member, this function returns undefined indicating that the
// Enum metaclass does not transform the value.
// By default, if a type annotation is present, the member is not treated
// as a member of the enumeration, but the Enum metaclass ignores such
// annotations. The typing spec indicates that the use of an annotation is
// illegal, so we need to detect this case and report an error.
/// TS defaults: ignoreAnnotation = false, recursionCount = 0.
pub fn transform_type_for_enum_member(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    member_name: &str,
    node_info: &dyn AnalyzerNodeInfoReader,
    ignore_annotation: bool,
    recursion_count: u32,
) -> Option<P<Type>> {
    if !ClassType::is_enum_class(class_type) {
        return None;
    }

    if recursion_count > MAX_TYPE_RECURSION_COUNT {
        return None;
    }
    let recursion_count = recursion_count + 1;

    // Avoid infinite recursion.
    let enum_eval_stack = ENUM_EVAL_STACK.with(|stack| stack.borrow().clone());
    if enum_eval_stack.iter().any(|entry| {
        ClassType::is_same_generic_class(entry.class_type, class_type, 0)
            && entry.member_name == member_name
    }) {
        return None;
    }

    ENUM_EVAL_STACK.with(|stack| {
        stack.borrow_mut().push(EnumEvalStackEntry {
            class_type,
            member_name: member_name.to_string(),
        })
    });

    // The `try` block; the `finally` pops the stack below.
    let result = (|| -> Option<P<Type>> {
        let member_info =
            look_up_class_member(class_type, member_name, MemberAccessFlags::Default, None)?;
        if !is_class(member_info.class_type)
            || !ClassType::is_enum_class(ClassType(member_info.class_type))
        {
            return None;
        }
        let member_class_type = ClassType(member_info.class_type);

        let decls = member_info.symbol.get_declarations();
        if decls.is_empty() {
            return None;
        }

        let primary_decl: P<Declaration> = decls[0];
        let primary_decl_node = primary_decl.node.get();

        let mut is_member_of_enumeration = false;
        let mut is_unpacked_tuple = false;
        let mut value_type_expr_node: Option<ExpressionNode> = None;
        let mut declared_type_node: Option<ExpressionNode> = None;

        let name_node = match primary_decl_node.node_type {
            ParseNodeType::Name => NameNode(primary_decl_node),
            // Handle the case where a method or class is decorated with @enum.member.
            ParseNodeType::Function => FunctionNode(primary_decl_node).d().name.get(),
            ParseNodeType::Class => ClassNode(primary_decl_node).d().name.get(),
            _ => return None,
        };

        let name_parent = name_node.parent.get();
        if let Some(assignment) = name_parent.and_then(AssignmentNode::cast)
            && assignment.d().left_expr.get() == name_node.0
        {
            is_member_of_enumeration = true;
            value_type_expr_node = Some(assignment.d().right_expr.get());
        } else if let Some(tuple_parent) =
            name_parent.filter(|parent| parent.node_type == ParseNodeType::Tuple)
            && let Some(assignment) = tuple_parent.parent.get().and_then(AssignmentNode::cast)
        {
            is_member_of_enumeration = true;
            is_unpacked_tuple = true;
            value_type_expr_node = Some(assignment.d().right_expr.get());
        } else if let Some(type_annotation) = name_parent.and_then(TypeAnnotationNode::cast)
            && type_annotation.d().value_expr.get() == name_node.0
        {
            if ignore_annotation {
                is_member_of_enumeration = true;
            }
            declared_type_node = Some(type_annotation.d().annotation.get());
        }

        // The spec specifically excludes names that start and end with a single underscore.
        // This also includes dunder names.
        if is_single_dunder_name(member_name) {
            return None;
        }

        // Specifically exclude "value" and "name". These are reserved by the enum metaclass.
        if member_name == "name" || member_name == "value" {
            return None;
        }

        let declared_type =
            declared_type_node.map(|node| evaluator.get_type_of_annotation(node, None));
        let mut assigned_type: Option<P<Type>> = None;

        if let Some(value_type_expr_node) = value_type_expr_node {
            let file_info = get_file_info(value_type_expr_node, node_info);
            let eval_flags = if file_info.is_stub_file {
                EvalFlags::ConvertEllipsisToAny
            } else {
                EvalFlags::None
            };
            assigned_type = Some(
                evaluator
                    .get_type_of_expression(value_type_expr_node, eval_flags, None)
                    .type_
                    .get(),
            );
        }

        // Handle aliases to other enum members within the same enum.
        if let Some(value_name_node) = value_type_expr_node.and_then(NameNode::cast)
            && value_name_node.d().value() != member_name
        {
            let aliased_enum_type = transform_type_for_enum_member(
                evaluator,
                class_type,
                value_name_node.d().value(),
                node_info,
                /* ignoreAnnotation */ false,
                recursion_count,
            );

            if let Some(aliased_enum_type) = aliased_enum_type
                && is_class_instance(aliased_enum_type)
                && ClassType::is_same_generic_class(
                    ClassType(aliased_enum_type),
                    ClassType::clone_as_instance(member_class_type, true),
                    0,
                )
                && ClassType(aliased_enum_type)
                    .d()
                    .priv_
                    .borrow()
                    .literal_value
                    .is_some()
            {
                return Some(aliased_enum_type);
            }
        }

        if let Some(function_node) = FunctionNode::cast(primary_decl_node) {
            let function_type_info = evaluator.get_type_of_function(function_node);
            if let Some(function_type_info) = function_type_info {
                assigned_type = Some(function_type_info.decorated_type);
            }
        } else if let Some(class_node) = ClassNode::cast(primary_decl_node) {
            let class_type_info = evaluator.get_type_of_class(class_node);
            if let Some(class_type_info) = class_type_info {
                assigned_type = Some(class_type_info.decorated_type);

                // If the class is not marked as a member or a non-member, the behavior
                // depends on the version of Python. In versions prior to 3.13, classes
                // are treated as members.
                if is_instantiable_class(class_type_info.decorated_type) {
                    let file_info = get_file_info(primary_decl_node, node_info);
                    is_member_of_enumeration = PythonVersion::is_less_than(
                        &file_info.execution_environment.python_version,
                        &PYTHON_VERSION3_13,
                    );
                }
            }
        }

        let mut value_type = declared_type
            .or(assigned_type)
            .unwrap_or_else(|| UnknownType::create(false).0);

        // If the LHS is an unpacked tuple, we need to handle this as
        // a special case.
        if is_unpacked_tuple {
            value_type = evaluator
                .get_type_of_iterator(
                    P::new_eval(TypeResult::new(value_type)),
                    /* isAsync */ false,
                    name_node.0,
                    /* emitNotIterableError */ false,
                )
                .map(|iterator_result| iterator_result.type_.get())
                .unwrap_or_else(|| UnknownType::create(false).0);
        }

        // The spec excludes descriptors.
        if is_class_instance(value_type)
            && ClassType::get_symbol_table(ClassType(value_type))
                .get("__get__")
                .is_some()
        {
            return None;
        }

        // The spec excludes private (mangled) names.
        if is_private_name(member_name) {
            return None;
        }

        // The enum spec doesn't explicitly specify this, but it
        // appears that callables are excluded.
        find_subtype(value_type, &mut |subtype| {
            !is_function_or_overloaded(subtype)
        })?;

        if assigned_type.is_none()
            && let Some(assignment) = name_node.parent.get().and_then(AssignmentNode::cast)
            && assignment.d().left_expr.get() == name_node.0
        {
            let inference_context = make_inference_context(declared_type, None, None);
            assigned_type = Some(
                evaluator
                    .get_type_of_expression(
                        assignment.d().right_expr.get(),
                        /* flags */ EvalFlags::None,
                        inference_context,
                    )
                    .type_
                    .get(),
            );
        }

        // Handle the Python 3.11 "enum.member()" and "enum.nonmember()" features.
        if let Some(assigned_type) = assigned_type
            && is_class_instance(assigned_type)
            && ClassType::is_built_in(ClassType(assigned_type), None)
        {
            let assigned_class = ClassType(assigned_type);
            let full_name = &assigned_class.d().shared.get().full_name;
            if full_name == "enum.nonmember" {
                let type_args = assigned_class.d().priv_.borrow().type_args.clone();
                let non_member_type = match &type_args {
                    Some(type_args) if !type_args.is_empty() => type_args[0],
                    _ => UnknownType::create(false).0,
                };

                // If the type of the nonmember is declared and the assigned value has
                // a compatible type, use the declared type.
                if let Some(declared_type) = declared_type
                    && evaluator.assign_type(
                        declared_type,
                        non_member_type,
                        None,
                        None,
                        AssignTypeFlags::Default,
                        0,
                    )
                {
                    return Some(declared_type);
                }

                return Some(non_member_type);
            }

            if full_name == "enum.member" {
                let type_args = assigned_class.d().priv_.borrow().type_args.clone();
                value_type = match &type_args {
                    Some(type_args) if !type_args.is_empty() => type_args[0],
                    _ => UnknownType::create(false).0,
                };
                is_member_of_enumeration = true;
            }
        }

        if !is_member_of_enumeration {
            return None;
        }

        let member_class_shared = member_class_type.d().shared.get();
        let enum_literal = EnumLiteral::new(
            member_class_shared.full_name.to_string(),
            member_class_shared.name.to_string(),
            member_name.to_string(),
            value_type,
            is_repr_enum_class(class_type),
        );

        Some(
            ClassType::clone_as_instance(
                ClassType::clone_with_literal(
                    member_class_type,
                    Some(LiteralValue::EnumLiteral(enum_literal)),
                ),
                true,
            )
            .0,
        )
    })();

    ENUM_EVAL_STACK.with(|stack| stack.borrow_mut().pop());

    result
}

// analyzer/enums.ts:545
pub fn is_decl_in_enum_class(evaluator: &TypeEvaluator, decl: P<Declaration>) -> bool {
    let Some(class_node) = get_enclosing_class(decl.node.get(), /* stopAtFunction */ true) else {
        return false;
    };

    let Some(class_info) = evaluator.get_type_of_class(class_node) else {
        return false;
    };

    ClassType::is_enum_class(class_info.class_type)
}

// analyzer/enums.ts:559
/// TS defaults: declaredTypesOnly = false.
pub fn get_enum_declared_value_type(
    evaluator: &TypeEvaluator,
    class_type: ClassType,
    declared_types_only: bool,
) -> Option<P<Type>> {
    // See if there is a declared type for "_value_".
    let mut value_type: Option<P<Type>> = None;

    let declared_value_member = look_up_class_member(
        class_type,
        "_value_",
        if declared_types_only {
            MemberAccessFlags::DeclaredTypesOnly
        } else {
            MemberAccessFlags::Default
        },
        None,
    );

    // If the declared type comes from the 'Enum' base class, ignore it
    // because it will be "Any", which isn't useful to us here.
    if let Some(declared_value_member) = &declared_value_member
        && is_class(declared_value_member.class_type)
        && !ClassType::is_built_in(
            ClassType(declared_value_member.class_type),
            Some(&[jsrt::atom!("Enum")]),
        )
    {
        value_type = Some(evaluator.get_type_of_member(declared_value_member));
    }

    value_type
}

// analyzer/enums.ts:587
pub fn get_type_of_enum_member(
    evaluator: &TypeEvaluator,
    error_node: P<ParseNode>,
    class_type: ClassType,
    member_name: &str,
    is_incomplete: bool,
    node_info: &AnalyzerNodeInfoAccessor,
) -> Option<P<TypeResult>> {
    // `{ type, isIncomplete }`.
    let make_result = |type_: P<Type>| {
        P::new_eval(TypeResult {
            is_incomplete: Cell::new(Some(is_incomplete)),
            ..TypeResult::new(type_)
        })
    };

    if !ClassType::is_enum_class(class_type) {
        return None;
    }

    let type_ = transform_type_for_enum_member(
        evaluator,
        class_type,
        member_name,
        node_info.reader(),
        false,
        0,
    );
    if let Some(type_) = type_ {
        return Some(make_result(type_));
    }

    if TypeBase::is_instantiable(class_type.0) {
        return None;
    }

    // Handle the special case of 'name' and 'value' members within an enum.
    let literal_value = class_type.d().priv_.borrow().literal_value.clone();
    // `if (literalValue)`: JS truthiness of the literal value.
    let is_literal_value_truthy = match &literal_value {
        None => false,
        Some(LiteralValue::Number(value)) => *value != 0.0 && !value.is_nan(),
        Some(LiteralValue::Bigint(value)) => !value.is_zero(),
        Some(LiteralValue::Boolean(value)) => *value,
        Some(LiteralValue::String(value)) => !value.is_empty(),
        Some(LiteralValue::EnumLiteral(_)) | Some(LiteralValue::SentinelLiteral(_)) => true,
    };

    if member_name == "name" || member_name == "_name_" {
        // Does the class explicitly override this member? Or it it using the
        // standard behavior provided by the "Enum" class?
        let member_info =
            look_up_class_member(class_type, member_name, MemberAccessFlags::Default, None);
        if let Some(member_info) = &member_info
            && is_class(member_info.class_type)
            && !ClassType::is_built_in(
                ClassType(member_info.class_type),
                Some(&[jsrt::atom!("Enum")]),
            )
        {
            return None;
        }

        let str_class = evaluator.get_built_in_type(error_node, "str");
        if !is_instantiable_class(str_class) {
            return None;
        }
        let str_class = ClassType(str_class);

        let make_name_type = |value: P<EnumLiteral>| {
            ClassType::clone_as_instance(
                ClassType::clone_with_literal(
                    str_class,
                    Some(LiteralValue::String((&value.item_name).into())),
                ),
                true,
            )
            .0
        };

        if is_literal_value_truthy {
            let Some(LiteralValue::EnumLiteral(literal_value)) = &literal_value else {
                panic!("assert(literalValue instanceof EnumLiteral)");
            };
            return Some(make_result(make_name_type(*literal_value)));
        }

        // The type wasn't associated with a particular enum literal, so return
        // a union of all possible enum literals.
        let literal_values = enumerate_literals_for_type(evaluator, class_type);
        if let Some(literal_values) = literal_values
            && !literal_values.is_empty()
        {
            let name_types: Vec<P<Type>> = literal_values
                .iter()
                .map(|literal_class| {
                    let literal_value = literal_class.d().priv_.borrow().literal_value.clone();
                    let Some(LiteralValue::EnumLiteral(literal_value)) = literal_value else {
                        panic!("assert(literalValue instanceof EnumLiteral)");
                    };
                    make_name_type(literal_value)
                })
                .collect();
            return Some(make_result(combine_types(&name_types, None)));
        }
    }

    // See if there is a declared type for "_value_".
    let value_type = get_enum_declared_value_type(evaluator, class_type, false);

    if member_name == "value" || member_name == "_value_" {
        // Does the class explicitly override this member? Or it it using the
        // standard behavior provided by the "Enum" class and other built-in
        // subclasses like "StrEnum" and "IntEnum"?
        let member_info =
            look_up_class_member(class_type, member_name, MemberAccessFlags::Default, None);
        if let Some(member_info) = &member_info
            && is_class(member_info.class_type)
            && !ClassType::is_built_in(ClassType(member_info.class_type), None)
        {
            return None;
        }

        // If the enum class has a custom metaclass, it may implement some
        // "magic" that computes different values for the "_value_" attribute.
        // This occurs, for example, in the django TextChoices class. If we
        // detect a custom metaclass, we'll use the declared type of _value_
        // if it is declared.
        let metaclass = class_type.d().shared.get().effective_metaclass.get();
        if let Some(metaclass) = metaclass
            && is_class(metaclass)
            && !ClassType::is_built_in(ClassType(metaclass), None)
        {
            return Some(make_result(
                value_type.unwrap_or_else(|| AnyType::create(false).0),
            ));
        }

        // If the enum class has a custom __new__ or __init__ method,
        // it may implement some magic that computes different values for
        // the "_value_" attribute. If we see a customer __new__ or __init__,
        // we'll assume the value type is what we computed above, or Any.
        let new_member = look_up_class_member(
            class_type,
            "__new__",
            MemberAccessFlags::SkipObjectBaseClass,
            None,
        );
        let init_member = look_up_class_member(
            class_type,
            "__init__",
            MemberAccessFlags::SkipObjectBaseClass,
            None,
        );

        if let Some(new_member) = &new_member
            && is_class(new_member.class_type)
            && !ClassType::is_built_in(ClassType(new_member.class_type), None)
        {
            return Some(make_result(
                value_type.unwrap_or_else(|| AnyType::create(false).0),
            ));
        }

        if let Some(init_member) = &init_member
            && is_class(init_member.class_type)
            && !ClassType::is_built_in(ClassType(init_member.class_type), None)
        {
            return Some(make_result(
                value_type.unwrap_or_else(|| AnyType::create(false).0),
            ));
        }

        // There were no explicit assignments to the "_value_" attribute, so we can
        // assume that the values are assigned directly to the "_value_" by
        // the EnumMeta metaclass.
        if is_literal_value_truthy {
            let Some(LiteralValue::EnumLiteral(literal_value)) = &literal_value else {
                panic!("assert(literalValue instanceof EnumLiteral)");
            };

            // If there is no known value type for this literal value,
            // return undefined. This will cause the caller to fall back
            // on the definition of "_value_" within the class definition
            // (if present).
            if is_any(literal_value.item_type) {
                return value_type.map(make_result);
            }

            return Some(make_result(literal_value.item_type));
        }

        // The type wasn't associated with a particular enum literal, so return
        // a union of all possible enum literals.
        let literal_values = enumerate_literals_for_type(evaluator, class_type);
        if let Some(literal_values) = literal_values
            && !literal_values.is_empty()
        {
            let item_types: Vec<P<Type>> = literal_values
                .iter()
                .map(|literal_class| {
                    let literal_value = literal_class.d().priv_.borrow().literal_value.clone();
                    let Some(LiteralValue::EnumLiteral(literal_value)) = literal_value else {
                        panic!("assert(literalValue instanceof EnumLiteral)");
                    };
                    literal_value.item_type
                })
                .collect();
            return Some(make_result(combine_types(&item_types, None)));
        }
    }

    None
}

// analyzer/enums.ts:724
pub fn get_enum_auto_value_type(evaluator: &TypeEvaluator, node: ExpressionNode) -> P<Type> {
    let containing_class_node = get_enclosing_class(node, false);

    if let Some(containing_class_node) = containing_class_node {
        let class_type_info = evaluator.get_type_of_class(containing_class_node);
        if let Some(class_type_info) = class_type_info {
            let member_info = evaluator.get_type_of_bound_member(
                Some(node),
                ClassType::clone_as_instance(class_type_info.class_type, true),
                "_generate_next_value_",
                &EvaluatorUsage {
                    method: "get".to_string(),
                    set_type: None,
                    set_error_node: None,
                    set_expected_type_diag: None,
                },
                None,
                MemberAccessFlags::Default,
                None,
                0,
            );

            // Did we find a custom _generate_next_value_ sunder override?
            // Ignore if this comes from Enum because it is declared as
            // returning an "Any" type in the typeshed stubs.
            if let Some(member_info) = member_info
                && !member_info.type_errors.get().unwrap_or(false)
                && is_function(member_info.type_.get())
                && let Some(member_class_type) = member_info.class_type
                && is_class(member_class_type)
                && !ClassType::is_built_in(
                    ClassType(member_class_type),
                    Some(&[jsrt::atom!("Enum")]),
                )
                && let Some(declared_return_type) = FunctionType(member_info.type_.get())
                    .d()
                    .shared
                    .get()
                    .declared_return_type
                    .get()
            {
                return declared_return_type;
            }
        }
    }

    evaluator.get_built_in_object(node, "int", None)
}

// analyzer/enums.ts:757
pub(crate) fn is_repr_enum_class(enum_class: ClassType) -> bool {
    let mro = enum_class.d().shared.get().mro.borrow().clone();
    mro.iter().any(|&mro_class| {
        is_class(mro_class)
            && ClassType::is_built_in(ClassType(mro_class), Some(&[jsrt::atom!("ReprEnum")]))
    })
}
